public class RequestLoggingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<RequestLoggingMiddleware> _logger;

    public RequestLoggingMiddleware(
        RequestDelegate next,
        ILogger<RequestLoggingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        _logger.LogInformation(
            "Request: {Method} {Path}",
            context.Request.Method,
            context.Request.Path);

        await _next(context);

        _logger.LogInformation(
            "Response: {StatusCode} for {Path}",
            context.Response.StatusCode,
            context.Request.Path);
    }
}

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddTransient<RequestLoggingMiddleware>();

var app = builder.Build();

app.UseMiddleware<RequestLoggingMiddleware>();

app.MapGet("/", () => "Hello World!");
app.Run();

public class RateLimitOptions
{
    public int MaxRequestsPerMinute { get; set; } = 60;
    public string BlockedPathPrefix { get; set; } = "/admin";
}

public class RateLimitMiddleware
{
    private readonly RequestDelegate _next;
    private readonly RateLimitOptions _options;
    private readonly ILogger<RateLimitMiddleware> _logger;
    private static readonly Dictionary<string, int> _requestCounts = new();

    public RateLimitMiddleware(
        RequestDelegate next,
        IOptions<RateLimitOptions> options,
        ILogger<RateLimitMiddleware> logger)
    {
        _next = next;
        _options = options.Value;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var key = context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
        var count = _requestCounts.GetValueOrDefault(key);

        if (count >= _options.MaxRequestsPerMinute)
        {
            context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            await context.Response.WriteAsync("Rate limit exceeded.");
            return;
        }

        _requestCounts[key] = count + 1;
        await _next(context);
    }
}

// Registration in Program.cs
builder.Services.Configure<RateLimitOptions>(builder.Configuration.GetSection("RateLimit"));
app.UseMiddleware<RateLimitMiddleware>();

public class ResponseHeaderMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ResponseHeaderMiddleware> _logger;

    public ResponseHeaderMiddleware(RequestDelegate next, ILogger<ResponseHeaderMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        context.Response.OnStarting(() =>
        {
            context.Response.Headers["X-App-Version"] = "1.0.0";
            context.Response.Headers["X-Request-Id"] = Guid.NewGuid().ToString();
            return Task.CompletedTask;
        });

        await _next(context);
    }
}
